func TestEnumBeaconUserStatus(t *testing.T) {
	t.Run("NewFromString_rejected", func(t *testing.T) {
		t.Parallel()
		val, err := NewBeaconUserStatusFromString("rejected")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, BeaconUserStatus("rejected"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_pending_review", func(t *testing.T) {
		t.Parallel()
		val, err := NewBeaconUserStatusFromString("pending_review")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, BeaconUserStatus("pending_review"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_cleared", func(t *testing.T) {
		t.Parallel()
		val, err := NewBeaconUserStatusFromString("cleared")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, BeaconUserStatus("cleared"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewBeaconUserStatusFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewBeaconUserStatusFromString("rejected")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

